userscript.function:

doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'CONNECTION', 'doDocumentDetail', {
    DOC_NO: docNo,
    MANAGE_NUMBER: manageNo,
    APPLY_TYPE: "LO",
    COMPANY_CODE: companyCode
}, function(so) {
    if (so.status == 1) {
        var soResult = new SepoaFormater(so.result[0]);
        formObj.dataMapper(soResult);
        var status = soResult.getArrayMap()[0].STATUS;
        if (status) {
            setModeByStatus(status, docNo);
        } else {
            Alert(Sepoa.cache.text.get('SLM_143.MESSAGE006'), function() { //문서의 상태를 확인할 수 없습니다.
                doBack();
            });
        }
        return true;
    } else {
        Alert(Sepoa.cache.text.get('MESSAGE.1002'));
        doBack();
        return false;
    }
});


if (formObj.getValue('SUBJECT') == "") {
    Alert(Sepoa.cache.text.get("SLM_143.MESSAGE001")); //인감을 선택해주세요.
    return;
}

var params = {};

var serviceData = {
    parameter: {
        basic_info: getCustomFormData()
    }
};

params.SEAL_DATA = JSON.stringify(serviceData);
params.CURRENT_PRC = 'CREATE';

if (callbackObj) {
    doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'TRANSACTION', 'doLossService', params, function(so) {
        if (so.status == 1) {
            callbackObj.CALLBACK(callbackObj.CALLBACK_PARMETER);
        } else {
            Alert(so.message);
        }
    });
} else {
    Confirm(Sepoa.cache.text.get('SLM_143.MESSAGE002'), function(flag) { //저장하시겠습니까?
        if (flag) {
            doServiceAjax('sepoa.svc.seal.SepoaSealManagementService', 'TRANSACTION', 'doLossService', params, function(so) {
                if (so.status == 1) {
                    Alert(Sepoa.cache.text.get("MESSAGE.0001"));
                } else {
                    Alert(so.message);
                }
            });
        }
    });
}


if (formObj.getValue("LOSS_USER_NAME") == "") {
