switch (status) {
    case "NEW":
        setNewMode();
        vaultInitSetting('upload',docNo);
        break;
    case "T":
        setEditMode();
        vaultInitSetting('upload',docNo);
        break;
    case "G":
        setReadMode();
        vaultInitSetting('VI',docNo);
        break;
    case "O":
        setReadMode();
        vaultInitSetting('VI',docNo);
        break;
    case "N":
        setReadMode();
        vaultInitSetting('VI',docNo);
        break;
    case "C":
        setReadMode();
        vaultInitSetting('VI',docNo);
        break;
    case "DETAIL":
        break;
    default:
        break;
}
setBtns(status);


hideAllBtn();
switch (status) {
    case "NEW":
        //btnObj.btn('SAVE').setShow();

        if (sUtils.workflow.check('SL1635987694555')) { //결재 모듈
            btnObj.btn('APP_REQUEST').setShow();
            return;
        }

        if (sUtils.workflow.check('SL1635987694835')) { //법무팀 승인 모듈
            btnObj.btn('LEGAL_REQUEST').setShow();
            return;
        }

        if (sUtils.workflow.check('SL1635987695123')) { //완료 모듈
			btnObj.btn('LOSS').setShow();
        }

        break;
    case "T":
        btnObj.btn('BACK').setShow();
        //btnObj.btn('SAVE').setShow();

        if (sUtils.workflow.check('SL1635987694555')) { //결재 모듈
            btnObj.btn('APP_REQUEST').setShow();
            return;
        }

        if (sUtils.workflow.check('SL1635987694835')) { //법무팀 승인 모듈
            btnObj.btn('LEGAL_REQUEST').setShow();
            return;
        }

        if (sUtils.workflow.check('SL1635987695123')) { //완료 모듈
			btnObj.btn('LOSS').setShow();
        }

        break;
    case "G":
        if (Sepoa.info.CTRL_CODE.indexOf('MANAGE_CONFIRM') > -1) {
            btnObj.btn('LEGAL_ACCEPT').setShow();
            btnObj.btn('LEGAL_REJECT').setShow();
        }
        btnObj.btn('BACK').setShow();
        break;
    case "O":
        btnObj.btn('BACK').setShow();
        break;
    case "N":
        btnObj.btn('BACK').setShow();
        break;
    case "C":
        btnObj.btn('BACK').setShow();
        break;
    case "DETAIL":
        break;
    default:
        break;
}


btnObj.forEachBtn(function(id) {
    btnObj.btn(id).setHide();
})


